15	/// RequestTemplate for GraphQL requests (See RequestTemplate documentation)
16	#[derive(Setters, Debug, Clone)]
17	pub struct RequestTemplate {
18	    // TODO: should be Mustache as for other templates
19	    pub url: String,
20	    pub operation_type: GraphQLOperationType,
