35	impl RequestTemplate {
36	    fn create_url<C: PathString>(&self, ctx: &C) -> Result<Url> {
37	        let url = url::Url::parse(self.url.render(ctx).as_str())?;
38	
39	        Ok(url)
40	    }
41	
42	    fn create_headers<C: PathString>(&self, ctx: &C) -> HeaderMap {
43	        let mut header_map = HeaderMap::new();
44	
45	        header_map.insert(CONTENT_TYPE, GRPC_MIME_TYPE.to_owned());
46	
47	        for (k, v) in &self.headers {
48	            if let Ok(header_value) = HeaderValue::from_str(&v.render(ctx)) {
49	                header_map.insert(k, header_value);
50	            }
51	        }
52	
53	        header_map
54	    }
55	
56	    pub fn render<C: PathString + HasHeaders>(&self, ctx: &C) -> Result<RenderedRequestTemplate> {
57	        let url = self.create_url(ctx)?;
58	        let headers = self.render_headers(ctx);
59	        let body = self.render_body(ctx);
60	        Ok(RenderedRequestTemplate { url, headers, body, operation: self.operation.clone() })
61	    }
62	
63	    fn render_body<C: PathString + HasHeaders>(&self, ctx: &C) -> String {
64	        if let Some(body) = &self.body {
65	            body.render(ctx)
66	        } else {
67	            "{}".to_owned()
68	        }
69	    }
70	
71	    fn render_headers<C: PathString + HasHeaders>(&self, ctx: &C) -> HeaderMap {
72	        let mut req_headers = HeaderMap::new();
73	
74	        let headers = self.create_headers(ctx);
75	        if !headers.is_empty() {
76	            req_headers.extend(headers);
77	        }
78	
79	        req_headers.extend(ctx.headers().to_owned());
80	
81	        req_headers
82	    }
83	}
