29	impl PathString for serde_json::Value {
30	    fn path_string<T: AsRef<str>>(&self, path: &[T]) -> Option<Cow<'_, str>> {
31	        self.get_path(path).map(|a| match a {
32	            serde_json::Value::String(s) => Cow::Borrowed(s.as_str()),
