38	fn convert_value(value: &async_graphql::Value) -> Option<Cow<'_, str>> {
39	    match value {
40	        async_graphql::Value::String(s) => Some(Cow::Borrowed(s.as_str())),
41	        async_graphql::Value::Number(n) => Some(Cow::Owned(n.to_string())),
42	        async_graphql::Value::Boolean(b) => Some(Cow::Owned(b.to_string())),
43	        async_graphql::Value::Object(map) => Some(json!(map).to_string().into()),
44	        async_graphql::Value::List(list) => Some(json!(list).to_string().into()),
45	        _ => None,
46	    }
47	}
