49	impl<'a, Ctx: ResolverContextLike<'a>> PathString for EvaluationContext<'a, Ctx> {
50	    fn path_string<T: AsRef<str>>(&self, path: &[T]) -> Option<Cow<'_, str>> {
51	        let ctx = self;
52	
53	        if path.is_empty() {
54	            return None;
55	        }
56	
57	        if path.len() == 1 {
58	            return match path[0].as_ref() {
59	                "value" => convert_value(ctx.path_value(&[] as &[T])?),
60	                "args" => Some(json!(ctx.graphql_ctx.args()?).to_string().into()),
61	                "vars" => Some(json!(ctx.vars()).to_string().into()),
62	                _ => None,
63	            };
64	        }
65	
66	        path.split_first()
67	            .and_then(|(head, tail)| match head.as_ref() {
68	                "value" => convert_value(ctx.path_value(tail)?),
69	                "args" => convert_value(ctx.arg(tail)?),
70	                "headers" => ctx.header(tail[0].as_ref()).map(|v| v.into()),
71	                "vars" => ctx.var(tail[0].as_ref()).map(|v| v.into()),
72	                "env" => ctx.env_var(tail[0].as_ref()).map(|v| v.into()),
73	                _ => None,
74	            })
75	    }
76	}
