78	impl<'a, Ctx: ResolverContextLike<'a>> PathGraphql for EvaluationContext<'a, Ctx> {
79	    fn path_graphql<T: AsRef<str>>(&self, path: &[T]) -> Option<String> {
80	        let ctx = self;
81	
82	        if path.len() < 2 {
83	            return None;
84	        }
85	
86	        path.split_first()
87	            .and_then(|(head, tail)| match head.as_ref() {
88	                "value" => Some(ctx.path_value(tail)?.to_string()),
89	                "args" => Some(ctx.arg(tail)?.to_string()),
90	                "headers" => ctx.header(tail[0].as_ref()).map(|v| format!(r#""{v}""#)),
91	                "vars" => ctx.var(tail[0].as_ref()).map(|v| format!(r#""{v}""#)),
92	                "env" => ctx.env_var(tail[0].as_ref()).map(|v| format!(r#""{v}""#)),
93	                _ => None,
94	            })
95	    }
96	}
