14	fn to_type_ref(type_of: &Type) -> dynamic::TypeRef {
15	    match type_of {
16	        Type::NamedType { name, non_null } => {
17	            if *non_null {
18	                dynamic::TypeRef::NonNull(Box::from(dynamic::TypeRef::Named(Cow::Owned(
19	                    name.clone(),
20	                ))))
21	            } else {
22	                dynamic::TypeRef::Named(Cow::Owned(name.clone()))
23	            }
24	        }
25	        Type::ListType { of_type, non_null } => {
26	            let inner = Box::new(to_type_ref(of_type));
27	            if *non_null {
28	                dynamic::TypeRef::NonNull(Box::from(dynamic::TypeRef::List(inner)))
29	            } else {
30	                dynamic::TypeRef::List(inner)
31	            }
32	        }
33	    }
34	}
