36	fn get_cache_key<'a, H: Hasher + Clone>(
37	    ctx: &'a EvaluationContext<'a, ResolverContext<'a>>,
38	    mut hasher: H,
39	) -> Option<u64> {
40	    // Hash on parent value
41	    if let Some(const_value) = ctx
42	        .graphql_ctx
43	        .parent_value
44	        .as_value()
45	        // TODO: handle _id, id, or any field that has @key on it.
46	        .filter(|value| value != &&ConstValue::Null)
47	        .map(|data| data.get_key("id"))
48	    {
49	        // Hash on parent's id only?
50	        helpers::value::hash(const_value?, &mut hasher);
51	    }
52	
53	    let key = ctx
54	        .graphql_ctx
55	        .args
56	        .iter()
57	        .map(|(key, value)| {
58	            let mut hasher = hasher.clone();
59	            key.hash(&mut hasher);
60	            helpers::value::hash(value.as_value(), &mut hasher);
61	            hasher.finish()
62	        })
63	        .fold(hasher.finish(), |acc, val| acc ^ val);
64	
65	    Some(key)
66	}
