68	fn to_type(def: &Definition) -> dynamic::Type {
69	    match def {
70	        Definition::ObjectTypeDefinition(def) => {
71	            let mut object = dynamic::Object::new(def.name.clone());
72	            for field in def.fields.iter() {
73	                let field = field.clone();
74	                let type_ref = to_type_ref(&field.of_type);
75	                let field_name = &field.name.clone();
76	                let cache = field.cache.clone();
77	                let mut dyn_schema_field = dynamic::Field::new(field_name, type_ref, move |ctx| {
78	                    let req_ctx = ctx.ctx.data::<Arc<RequestContext>>().unwrap();
79	                    let field_name = &field.name;
80	                    match &field.resolver {
81	                        None => {
82	                            let ctx = EvaluationContext::new(req_ctx, &ctx);
83	                            FieldFuture::from_value(
84	                                ctx.path_value(&[field_name]).map(|a| a.to_owned()),
85	                            )
86	                        }
87	                        Some(expr) => {
88	                            let expr = expr.to_owned();
89	                            let cache = cache.clone();
90	                            FieldFuture::new(async move {
91	                                let ctx = EvaluationContext::new(req_ctx, &ctx);
92	
93	                                let ttl_and_key =
94	                                    cache.and_then(|Cache { max_age: ttl, hasher }| {
95	                                        Some((ttl, get_cache_key(&ctx, hasher)?))
96	                                    });
97	                                let const_value = match ttl_and_key {
98	                                    Some((ttl, key)) => {
