100	                                            ctx.req_ctx.cache_get(&key).await?
101	                                        {
102	                                            // Return value from cache
103	                                            log::info!("Reading from cache. key = {key}");
104	                                            const_value
105	                                        } else {
106	                                            let const_value =
107	                                                expr.eval(&ctx, &Concurrent::Sequential).await?;
108	                                            log::info!("Writing to cache. key = {key}");
109	                                            // Write value to cache
110	                                            ctx.req_ctx
111	                                                .cache_insert(key, const_value.clone(), ttl)
112	                                                .await?;
113	                                            const_value
114	                                        }
115	                                    }
116	                                    _ => expr.eval(&ctx, &Concurrent::Sequential).await?,
117	                                };
118	
119	                                let p = match const_value {
120	                                    ConstValue::List(a) => FieldValue::list(a),
121	                                    a => FieldValue::from(a),
122	                                };
123	                                Ok(Some(p))
124	                            })
125	                        }
126	                    }
127	                });
