129	                    dyn_schema_field = dyn_schema_field.description(description);
130	                }
131	                for arg in field.args.iter() {
132	                    dyn_schema_field = dyn_schema_field.argument(dynamic::InputValue::new(
133	                        arg.name.clone(),
