impl<Ctx: PathString + HasHeaders> CacheKey<Ctx> for RequestTemplate {
    fn cache_key(&self, ctx: &Ctx) -> u64 {
        let mut hasher = std::collections::hash_map::DefaultHasher::new();
        let state = &mut hasher;

        // Hash the fully rendered url
        if let Ok(url) = self.create_url(ctx) {
            url.hash(state);
        }

        // Hash all the header names and values
        let headers = self.create_headers(ctx);
        for (name, value) in headers.iter() {
            name.hash(state);
            value.hash(state);
        }

        // Hash the rendered body
        if let Some(body) = &self.body_path {
            body.render(ctx).hash(state);
        }

        hasher.finish()
    }
